j:jelly.script:
function getMetadataForDisplay() {
var metadataJSON = '$[${ref_parent}.metadata]';
var className = '$[${ref_parent}.sys_class_name]';
var type = '$[${ref_parent}.type]';

var rtrnJSON = {};
// Initializing return value
rtrnJSON.label = "${gs.getMessage('Metadata')}";
rtrnJSON.title = "${gs.getMessage('General purpose service metadata to be (optionally) used during service population')}";
rtrnJSON.content = metadataJSON;

try {
var metadata;
if (className == 'cmdb_ci_service_calculated' &amp;&amp; type == '5') {
// Dynamic manual services
metadata = JSON.parse(metadataJSON);
var levels = metadata.levels;
if (!levels)
levels = 3;

rtrnJSON.label = "${gs.getMessage('Levels')}";
rtrnJSON.title = "${gs.getMessage('The number of levels of related CIs included in this application service')}";
rtrnJSON.content = levels;
} else if (className == 'cmdb_ci_service_by_tags') {
// Tag-based service
metadata = JSON.parse(metadataJSON);
var categoryValues = metadata.category_values;
if (!categoryValues)
categoryValues = [];

rtrnJSON.label = "${gs.getMessage('Category Values')}";
rtrnJSON.title = "${gs.getMessage('The list of tag category values that define the service structure')}";
rtrnJSON.content = formatCategoryValues(categoryValues);
}
} catch (e) {
// Do nothing
}

return rtrnJSON;
}

function formatCategoryValues(categoryValues) {
var categoryLabel = "${gs.getMessage('Category')}";
var valueLabel = "${gs.getMessage('Value')}";

var content = '';

for (var i = 0 ; i &lt; categoryValues.length ; i++) {
var category2Value = categoryValues[i];
var category = category2Value.category;
var value = category2Value.value;

if (content != '')
content += '\n';

content += (i+1) + '. ' + categoryLabel + ': ' + category + ', ' + valueLabel + ': ' + value;
}

return content;
}

$j(document).ready(function() {
var metadata = getMetadataForDisplay();
var labelSpan = $j("#metadata_json_label_span");
var textArea = $j("#metadata_json_textarea");
labelSpan.html(metadata.label);
labelSpan.attr('title', metadata.title);
textArea.attr('aria-label', metadata.label);
textArea.css('display', 'inline');
textArea.html(metadata.content);
});
